INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7fded1c2-46aa-483e-a0c5-3b254ebf399f', 'c3c3c3c3-3030-4000-8000-000000000003', 28, 'Dia 28 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor\u2026 e n\u00e3o te estribes no teu pr\u00f3prio entendimento. Clareza final vem da rendi\u00e7\u00e3o.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. O caminho da confian\u00e7a.", "practice": "Entregue uma decis\u00e3o a Deus hoje. Confie sem entender.", "question": "Em que \u00e1rea voc\u00ea tenta entender quando deveria confiar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;